namespace Kaff.Api.Features.DailyLogs.RecordMaterial;

/// <summary>Material on site by type. A count, never a value.</summary>
/// <param name="EntryId">Generated by the device, so a retried sync is recognised and not counted twice.</param>
/// <param name="OccurredAt">When it happened on site, with the device's offset. Decides which day the entry belongs to.</param>
public sealed record Request(Guid? EntryId, DateTimeOffset? OccurredAt, string? MaterialType, decimal Quantity, string? Unit, bool IsStockpile);
